<template><div class="page"><div class="page-header"><h2>通知模板</h2><el-button type="primary" size="small" @click="openCreate">新建模板</el-button></div><el-card shadow="never"><div class="filter-bar"><el-select v-model="filterRefType" placeholder="业务类型" size="small" clearable style="width:140px" @change="doSearch"><el-option label="派工通知" value="dispatch"/><el-option label="工单通知" value="maintenance"/></el-select><el-select v-model="filterUseflg" placeholder="有效状态" size="small" style="width:110px" @change="doSearch"><el-option label="所有" value=""/><el-option label="有效" value="1"/><el-option label="无效" value="0"/></el-select></div><el-table :data="items" v-loading="loading" stripe size="small" highlight-current-row @row-click="open"><el-table-column prop="template_id" label="模板ID" width="120"/><el-table-column prop="template_name" label="模板名称" min-width="140"/><el-table-column label="业务类型" width="110"><template #default="{row}"><el-tag size="small">{{ refTypeLabel(row.ref_type) }}</el-tag></template></el-table-column><el-table-column label="渠道" width="80"><template #default="{row}"><el-tag size="small">{{ row.channel }}</el-tag></template></el-table-column><el-table-column label="默认" width="70"><template #default="{row}"><el-tag v-if="row.is_default==='1'" type="success" size="small">默认</el-tag><span v-else>-</span></template></el-table-column><el-table-column prop="sort_no" label="排序" width="70"/><el-table-column prop="subject" label="标题" min-width="150" show-overflow-tooltip/><el-table-column label="有效" width="60"><template #default="{row}"><el-tag :type="row.useflg==='1'?'success':'info'" size="small">{{ row.useflg==='1'?'是':'否' }}</el-tag></template></el-table-column><el-table-column prop="gendate" label="创建日期" width="100"/><el-table-column label="操作" width="140" fixed="right"><template #default="{row}"><el-button type="primary" link size="small" @click.stop="openEdit(row)">编辑</el-button><el-button v-if="row.is_default!=='1'" type="success" link size="small" @click.stop="set_default(row)">设为默认</el-button></template></el-table-column></el-table><AppPagination v-model:current-page="page" v-model:page-size="perPage" :total="total" style="margin-top:12px;justify-content:flex-end"/></el-card><el-dialog :title="editTitle" v-model="editDrawer" width="900px" @close="onCloseEdit"><div class="tpl-editor"><div class="tpl-form"><el-form :model="form" label-width="90px" size="small"><el-form-item label="模板ID"><el-input v-model="form.template_id" :disabled="!isCreate" placeholder="如 DISPATCH"/></el-form-item><el-form-item label="模板名称"><el-input v-model="form.template_name"/></el-form-item><el-form-item label="业务类型"><el-select v-model="form.ref_type" style="width:100%" placeholder="选择业务类型" clearable><el-option v-for="r in refTypeOptions" :key="r.value" :label="r.label" :value="r.value"/></el-select></el-form-item><el-form-item label="渠道"><el-select v-model="form.channel" style="width:100%"><el-option v-for="c in channels" :key="c.channel" :label="c.label" :value="c.channel"/></el-select></el-form-item><el-form-item label="排序号"><el-input-number v-model="form.sort_no" :min="0" :max="9999" controls-position="right"/><span class="hint">数字小优先</span></el-form-item><el-form-item label="设为默认"><el-switch v-model="form.is_default" active-value="1" inactive-value="0"/><span class="hint">同业务类型下仅一个默认</span></el-form-item><el-form-item label="有效"><el-switch v-model="form.useflg" active-value="1" inactive-value="0"/></el-form-item><el-form-item label="标题模板"><el-input v-model="form.subject" type="textarea" @focus="focusedField='subject'" :rows="2" @input="schedulePreview"/></el-form-item><el-form-item label="正文模板"><el-input v-model="form.body" type="textarea" @focus="focusedField='body'" :rows="8" @input="schedulePreview"/></el-form-item><el-form-item label="变量插入"><div class="var-buttons"><el-button v-for="v in variables" :key="v" size="small" @click="insertVar(v)">{{ varLabelMap[v] || v }}</el-button></div></el-form-item></el-form></div><div class="tpl-preview"><h4>实时预览</h4><div class="preview-block"><strong>标题:</strong><div class="preview-content">{{ preview.subject || '-' }}</div></div><div class="preview-block"><strong>正文:</strong><pre class="preview-content">{{ preview.body || '-' }}</pre></div><div v-if="preview.error" class="preview-error">渲染错误: {{ preview.error }}</div></div></div><template #footer><el-button @click="editDrawer=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup lang="ts">import {ref,reactive,onMounted} from 'vue';import {ElMessage} from 'element-plus';import AppPagination from '@/components/common/AppPagination.vue';import {useListPage} from '@/composables/useListPage';import {fetchNotifTemplates,createNotifTemplate,updateNotifTemplate,setDefaultNotifTemplate,previewNotifTemplate,fetchChannels} from '@/api/notification';import type {NotifRecord,ChannelInfo} from '@/api/notification'
const{items,loading,page,perPage,total,onSearch}=useListPage<NotifRecord>(fetchNotifTemplates)
const channels=ref<ChannelInfo[]>([]);const focusedField=ref<'subject'|'body'>('body')
const refTypeOptions=[{value:'dispatch',label:'派工通知'},{value:'maintenance',label:'工单通知'}]
const filterRefType=ref('');const filterUseflg=ref('');function doSearch(){const p:Record<string,string>={};if(filterRefType.value)p.ref_type=filterRefType.value;if(filterUseflg.value)p.useflg=filterUseflg.value;onSearch(p)}
function refTypeLabel(v:unknown):string{const s=String(v||'');const o=refTypeOptions.find(r=>r.value===s);return o?o.label:(s||'-')}
const editDrawer=ref(false);const isCreate=ref(false)
onMounted(async()=>{try{const res=await fetchChannels();channels.value=res.data.channels.filter(c=>c.enabled)}catch{channels.value=[{channel:'internal',label:'站内通知',require_config:'否',enabled:true,implemented:true}]}})
const form=reactive<{template_id:string;template_name:string;channel:string;ref_type:string;is_default:string;sort_no:number;subject:string;body:string;useflg:string}>({template_id:'',template_name:'',channel:'internal',ref_type:'',is_default:'0',sort_no:0,subject:'',body:'',useflg:'1'})
const preview=reactive<{subject:string;body:string;error?:string}>({subject:'',body:''})
const variables=['maintenance_id','store_id','cust_card','cust_nm','address','phone_no','contactor','comm_mode','class_cd','area_cd','area_nm','fault_type','fault_type_nm','short_description','detail_description','device_id','request_time','current_status','current_status_nm','emergency_level','requester','expected_completion_time','accpectder','accpectder_nm','accpectd_group','operator','operator_nm','dispatch_time','business_operation_id']
const varLabelMap:Record<string,string>={'maintenance_id':'维护单号','store_id':'门店编码','cust_card':'磁卡号','cust_nm':'客户名称','address':'地址','phone_no':'电话','contactor':'联系人','comm_mode':'通讯方式','class_cd':'客户分类编码','area_cd':'区域编码','area_nm':'区域名称','fault_type':'故障类型编码','fault_type_nm':'故障类型','short_description':'故障简述','detail_description':'详细描述','device_id':'设备编号','request_time':'报修时间','current_status':'状态编码','current_status_nm':'当前状态','emergency_level':'紧急程度','requester':'报修人','expected_completion_time':'考核时间','accpectder':'分派人编码','accpectder_nm':'分派人','accpectd_group':'分派组','operator':'操作员编码','operator_nm':'操作员','dispatch_time':'派工时间','business_operation_id':'流水号'};let previewTimer:ReturnType<typeof setTimeout>|null=null
const editTitle=ref('编辑模板')
function open(){/* row-click 不打开详情，改用编辑按钮 */}
function openCreate(){isCreate.value=true;editTitle.value='新建模板';Object.assign(form,{template_id:'',template_name:'',channel:'internal',ref_type:'',is_default:'0',sort_no:0,subject:'',body:'',useflg:'1'});Object.assign(preview,{subject:'',body:''});editDrawer.value=true}
function openEdit(row:NotifRecord){isCreate.value=false;editTitle.value='编辑模板 - '+row.template_id;Object.assign(form,{template_id:String(row.template_id||''),template_name:String(row.template_name||''),channel:String(row.channel||'internal'),ref_type:String(row.ref_type||''),is_default:String(row.is_default||'0'),sort_no:Number(row.sort_no||0),subject:String(row.subject||''),body:String(row.body||''),useflg:String(row.useflg||'1')});schedulePreview();editDrawer.value=true}
async function set_default(row:NotifRecord){try{await setDefaultNotifTemplate(String(row.template_id));ElMessage.success('已设为默认');onSearch({})}catch{ElMessage.error('设置失败')}}
function insertVar(v:string){if(focusedField.value==='subject')form.subject=form.subject+`{{ ${v} }}`;else form.body=form.body+`{{ ${v} }}`;schedulePreview()}
function schedulePreview(){if(previewTimer)clearTimeout(previewTimer);previewTimer=setTimeout(doPreview,400)}
async function doPreview(){try{const res=await previewNotifTemplate({subject:form.subject,body:form.body});Object.assign(preview,{subject:res.data.subject,body:res.data.body,error:res.data.error})}catch(e){Object.assign(preview,{subject:'',body:'',error:String(e)})}}
async function save(){if(!form.template_id){ElMessage.warning('请输入模板ID');return}try{const payload={template_id:form.template_id,template_name:form.template_name,channel:form.channel,ref_type:form.ref_type,is_default:form.is_default,sort_no:form.sort_no,subject:form.subject,body:form.body,useflg:form.useflg};if(isCreate.value){await createNotifTemplate(payload);ElMessage.success('创建成功')}else{await updateNotifTemplate(form.template_id,payload);ElMessage.success('更新成功')}editDrawer.value=false;onSearch({})}catch{ElMessage.error('保存失败')}}
function onCloseEdit(){if(previewTimer)clearTimeout(previewTimer)}
</script>
<style scoped>.page{padding:0}.page-header{display:flex;justify-content:space-between;align-items:center;margin-bottom:16px}.page-header h2{font-size:18px;font-weight:600;margin:0}.filter-bar{margin-bottom:12px}.tpl-editor{display:flex;gap:16px}.tpl-form{flex:1}.tpl-preview{flex:1;border-left:1px solid #ebeef5;padding-left:16px}.var-buttons{display:flex;flex-wrap:wrap;gap:4px}.preview-block{margin-bottom:12px}.preview-content{margin-top:4px;background:#f5f7fa;padding:8px;border-radius:4px;white-space:pre-wrap;font-size:13px;min-height:24px}.preview-error{color:#f56c6c;font-size:12px;margin-top:8px}.hint{margin-left:8px;color:#909399;font-size:12px}</style>
